674	  private getResponseFormatKey(
675	    responseFormat?: ResponseFormat | null,
676	  ): string | undefined {
677	    if (!responseFormat) {
678	      return undefined;
679	    }
680	    if (responseFormat.type === "json_object") {
681	      return responseFormat.schema ?? undefined;
682	    }
683	    if (responseFormat.type === "grammar") {
684	      return responseFormat.grammar ?? undefined;
685	    }
686	    if (responseFormat.type === "structural_tag") {
687	      const structuralTag = responseFormat.structural_tag;
688	      if (structuralTag === undefined || structuralTag === null) {
689	        return undefined;
690	      }
691	      return typeof structuralTag === "string"
692	        ? structuralTag
693	        : JSON.stringify(structuralTag);
694	    }
695	    return undefined;
696	  }
