719	  /**
720	   * Generate the first token given input prompt
721	   */
722	  async prefillStep(
723	    inp: string,
724	    msgRole: Role, // either user or tool
725	    inp_role_str?: string,
726	    genConfig?: GenerationConfig,
727	  ): Promise<void> {
728	    if (msgRole !== Role.user && msgRole !== Role.tool) {
729	      throw new MessageOrderError(
730	        "The last message should be from `user` or `tool`.",
731	      );
732	    }
733	    if (this.resetStatsPerPrefill) {
734	      this.resetRuntimeStats();
735	    }
736	
737	    const tstart = performance.now();
738	
739	    // cleanup the per convo states
740	    this.outputIds = [];
741	    this.appearedTokensFreq.clear();
742	    this.outputMessage = "";
743	    this.tokenLogprobArray = [];
744	    this.curRoundDecodingTotalTokens = 0;
745	    this.curRoundPrefillTotalTokens = 0;
746	    this.curRoundPrefillTotalTime = 0;
747	    this.curRoundDecodingTotalTime = 0;
748	    this.curRoundGrammarInitTotalTime = 0;
749	    this.curRoundGrammarPerTokenTotalTime = 0;
750	
751	    this.curRoundLatencyBreakdown = {
752	      logitProcessorTime: [],
753	      logitBiasTime: [],
754	      penaltyTime: [],
755	      sampleTime: [],
756	      totalTime: [],
757	      grammarBitmaskTime: [],
758	    };
759	
760	    this.stopTriggered = false;
761	    const conversation = this.conversation;
762	
763	    // -1. Instantiate grammar matcher according to generation config. This step is overlapped
764	    // with prefilling the prompt to hide overhead by using this promise.
765	    let grammarMatcherInitPromise: Promise<void> | undefined = undefined;
766	    const responseFormat = genConfig?.response_format;
767	    if (
768	      responseFormat?.type === "json_object" ||
769	      responseFormat?.type === "grammar" ||
770	      responseFormat?.type === "structural_tag"
771	    ) {
772	      const curResponseFormatKey = this.getResponseFormatKey(responseFormat);
773	      if (
774	        curResponseFormatKey === this.responseFormatCacheKey &&
775	        this.grammarMatcher
776	      ) {
777	        // If we did not change the schema and have instantiated a GrammarMatcher, we reuse it.
778	        const tGrammarInitStart = performance.now();
779	        log.info("Reuse grammar matcher.");
780	        this.grammarMatcher.reset();
781	        this.curRoundGrammarInitTotalTime =
782	          (performance.now() - tGrammarInitStart) / 1e3;
783	      } else {
784	        // Else dispose current grammarMatcher, reinitialize, and update this.schema.
785	        /* eslint-disable no-async-promise-executor */
786	        grammarMatcherInitPromise = new Promise(async (resolve) => {
787	          const tGrammarInitStart = performance.now();
788	          log.info("Initialize new grammar matcher.");
789	          if (this.grammarMatcher) {
790	            this.grammarMatcher.dispose();
791	          }
792	          if (this.xgTokenizerInfo === undefined) {
793	            log.info("Initialize token table.");
794	            // Post process entire table
795	            const rawTokenTable = getTokenTableFromTokenizer(this.tokenizer);
796	            this.xgTokenizerInfo = await xgr.TokenizerInfo.createTokenizerInfo(
797	              rawTokenTable,
798	              this.token_postproc_method,
799	              this.prepend_space_in_encode,
800	              this.fullVocabSize,
801	              this.stopTokens,
802	            );
803	            this.grammarCompiler =
804	              await xgr.GrammarCompiler.createGrammarCompiler(
805	                this.xgTokenizerInfo,
806	              );
807	          }
808	          const grammar: xgr.CompiledGrammar =
809	            responseFormat.type === undefined
810	              ? await this.grammarCompiler!.compileBuiltinJSONGrammar()
811	              : responseFormat.type === "json_object"
812	                ? await this.grammarCompiler!.compileJSONSchema(
813	                    responseFormat.schema!,
814	                  )
815	                : responseFormat.type === "grammar"
816	                  ? await this.grammarCompiler!.compileGrammar(
817	                      responseFormat.grammar!,
818	                    )
819	                  : await this.grammarCompiler!.compileStructuralTag(
820	                      responseFormat.structural_tag!,
821	                    );
822	          this.grammarMatcher =
823	            await xgr.GrammarMatcher.createGrammarMatcher(grammar);
824	          grammar.dispose();
825	          this.responseFormatCacheKey = curResponseFormatKey;
826	          this.curRoundGrammarInitTotalTime =
827	            (performance.now() - tGrammarInitStart) / 1e3;
828	          resolve();
829	        });
830	      }
831	    }
832	
833	    // 0. Get inputData from conversation
834	    if (conversation.isTextCompletion) {
835	      conversation.prompt = inp;
836	    } else {
837	      conversation.appendMessage(msgRole, inp, inp_role_str);
838	      if (genConfig?.enable_thinking === false) {
839	        // TODO(Charlie): In future we should make emptyThinkingBlockStr configurable.
840	        const emptyThinkingBlockStr = "<think>\n\n</think>\n\n";
841	        const encoded = this.tokenizer.encode(emptyThinkingBlockStr);
842	        this.outputIds.push(...encoded);
843	        conversation.appendEmptyThinkingReplyHeader(
844	          Role.assistant,
845	          emptyThinkingBlockStr,
846	        );
847	      } else {
848	        conversation.appendReplyHeader(Role.assistant);
849	      }
850	    }
851	    const [inputData, promptLen, getEmbedSize] = await this.getInputData();
852	
853	    // Check if LLMChatPipeline fits for forwarding image input
854	    const hasImageInput = inputData.some((data) => !Array.isArray(data));
855	    if (hasImageInput && this.image_embed === undefined) {
856	      throw new CannotFindImageEmbedError();
857	    }
858	
859	    // 1. Chunk inputData to embed and forward in one shot for each, minimize intermediate data
860	    const retGetChunks = getChunkedPrefillInputData(
861	      inputData,
862	      this.prefillChunkSize,
863	      getEmbedSize,
864	    );
865	    const chunks: Array<Array<number> | ImageURL>[] = retGetChunks[0];
866	    const chunkLens: Array<number> = retGetChunks[1];
867	
868	    // 2. Prefill each chunk
869	    this.tvm.beginScope();
870	    let logits: tvmjs.Tensor;
871	    for (let i = 0; i < chunks.length; i++) {
872	      const chunk = chunks[i];
873	      const chunkLen = chunkLens[i];
874	      const prevFilledLen = this.filledKVCacheLength;
875	      logits = this.tvm.detachFromCurrentScope(
876	        await this.embedAndForward(chunk, chunkLen),
877	      );
878	      if (this.filledKVCacheLength !== prevFilledLen + chunkLen) {
879	        throw new Error(
880	          "Internal Error: filledKVCacheLength does not match expected value.",
881	        );
882	      }
883	    }
884	    this.imageDataCache.clear();
885	    this.tvm.endScope();
886	
887	    // 4. Sample, stats, post process token sampled.
888	    // We wait for prefill and grammar matcher init to finish
889	    await Promise.all([this.device.sync(), grammarMatcherInitPromise]);
890	    const nextToken = await this.sampleTokenFromLogits(logits!, genConfig);
891	    logits!.dispose();
892	    const tend = performance.now();
893	
894	    this.prefillTotalTime += (tend - tstart) / 1e3;
895	    this.prefillTotalTokens += promptLen;
896	    this.curRoundPrefillTotalTokens += promptLen;
897	    this.curRoundPrefillTotalTime += (tend - tstart) / 1e3;
898	
899	    this.processNextToken(nextToken, genConfig);
900	  }
