902	  async decodeStep(genConfig?: GenerationConfig): Promise<void> {
903	    if (this.stopTriggered) {
904	      throw Error("Cannot run decode when stopped");
905	    }
906	
907	    const tstart = performance.now();
908	
909	    this.tvm.beginScope();
910	    const chunk: Array<Array<number>> = [
911	      this.outputIds.slice(this.outputIds.length - 1),
912	    ];
913	    const chunkLen = chunk.length;
914	    const prevFilledLen = this.filledKVCacheLength;
915	    const logits = this.tvm.detachFromCurrentScope(
916	      await this.embedAndForward(chunk, chunkLen),
917	    );
918	    if (this.filledKVCacheLength !== prevFilledLen + chunkLen) {
919	      throw new Error(
920	        "Internal Error: filledKVCacheLength does not match expected value.",
921	      );
922	    }
923	    this.tvm.endScope();
924	
925	    // sample from logits
926	    const nextToken = await this.sampleTokenFromLogits(logits, genConfig);
927	    logits.dispose();
928	    const tend = performance.now();
929	
930	    this.decodingTotalTime += (tend - tstart) / 1e3;
931	    this.decodingTotalTokens += 1;
932	    this.curRoundDecodingTotalTokens += 1;
933	    this.curRoundDecodingTotalTime += (tend - tstart) / 1e3;
934	
935	    this.processNextToken(nextToken, genConfig);
936	  }
