938	  /**
939	   * Manually trigger stop if it is not stopped.
940	   */
941	  triggerStop() {
942	    if (this.stopTriggered) {
943	      return;
944	    }
945	    this.stopTriggered = true;
946	    this.finishReason = "abort";
947	    if (!this.conversation.isTextCompletion) {
948	      this.conversation.finishReply(this.outputMessage);
949	    }
