952	  /**
953	   * Add a generated token and check for stop.
954	   *
955	   * @param nextToken The next token.
956	   * @param genConfig Configs that override `this.config` for this round of generation.
957	   */
958	  private processNextToken(
959	    nextToken: number,
960	    genConfig?: GenerationConfig,
961	  ): void {
962	    if (this.stopTriggered) {
963	      throw Error("Cannot call process when it is stoppped");
964	    }
965	
966	    // Get max_tokens from generationConfig (specified by user in completion request)
967	    // If not specified, do not set a limit
968	    let max_tokens = Infinity;
969	    if (genConfig !== undefined && genConfig.max_tokens) {
970	      max_tokens = genConfig.max_tokens;
971	    }
972	    if (max_tokens <= 0) {
973	      throw new MinValueError("max_tokens", 0);
974	    }
975	
976	    // Get ignore_eos from generationConfig (specified by user in completion request)
977	    let ignore_eos = false;
978	    if (
979	      genConfig !== undefined &&
980	      genConfig.ignore_eos !== undefined &&
981	      genConfig.ignore_eos !== null
982	    ) {
983	      ignore_eos = genConfig.ignore_eos;
984	    }
985	
986	    // Get stopStrs, possibly overridden by genConfig for this round
987	    let stopStrs = this.stopStr;
988	    if (genConfig !== undefined && genConfig.stop) {
989	      stopStrs = stopStrs.concat(genConfig.stop);
990	    }
991	
992	    let stopTokens = this.stopTokens;
993	    if (ignore_eos) {
994	      stopTokens = [];
995	      stopStrs = [];
996	    }
997	
998	    // Stop condition 1: stop token; otherwise, append to `this.outputIds`
999	    if (stopTokens.includes(nextToken)) {
1000	      this.stopTriggered = true;
1001	      this.finishReason = "stop";
1002	    }
1003	    if (!this.stopTriggered) {
1004	      this.outputIds.push(nextToken);
1005	      // Update token appearance frequency
1006	      const curFreq = this.appearedTokensFreq.get(nextToken);
1007	      if (curFreq !== undefined) {
1008	        this.appearedTokensFreq.set(nextToken, curFreq + 1);
1009	      } else {
1010	        this.appearedTokensFreq.set(nextToken, 1);
1011	      }
1012	    }
1013	
1014	    // Stop condition 2: stop string; update `this.outputMessage` subsequently
1015	    let outputMessage = this.tokenizer.decode(new Int32Array(this.outputIds));
1016	    let stopPos = -1;
1017	    for (const stopStr of stopStrs) {
1018	      // Stop at the first stopStr we find
1019	      stopPos = outputMessage.lastIndexOf(stopStr);
1020	      if (stopPos != -1) {
1021	        outputMessage = outputMessage.substring(0, stopPos);
1022	        this.stopTriggered = true;
1023	        this.finishReason = "stop";
1024	        break;
1025	      }
1026	    }
1027	    this.outputMessage = outputMessage;
1028	
1029	    // Stop condition 3: exceed max_tokens
1030	    if (this.outputIds.length >= max_tokens) {
1031	      this.stopTriggered = true;
1032	      this.finishReason = "length";
1033	      log.info("Generation stopped due to exceeding max_tokens.");
1034	    }
1035	
1036	    // Stop condition 4: exceed KVCache's context window size
1037	    if (
1038	      this.slidingWindowSize == -1 &&
1039	      this.filledKVCacheLength == this.contextWindowSize
1040	    ) {
1041	      this.stopTriggered = true;
1042	      this.finishReason = "length";
1043	      log.info("Generation stopped due to exceeding context_window_size.");
1044	    }
1045	
1046	    // Finally, modify conversation history if stopped
1047	    if (this.stopTriggered) {
1048	      if (!this.conversation.isTextCompletion) {
1049	        this.conversation.finishReply(this.outputMessage);
1050	      }
1051	    }
1052	  }
