1054	  /**
1055	   * Given input tokens, return embeddings of them by calling embed kernel.
1056	   *
1057	   * @note precondition: inputTokens.length <= prefillChunkSize, since we take care of
1058	   * chunking in `getChunkedPrefillInputData()`.
1059	   */
1060	  private getTokensEmbeddings(inputTokens: number[]): tvmjs.Tensor {
1061	    this.tvm.beginScope();
1062	    if (inputTokens.length > this.prefillChunkSize) {
1063	      throw new Error(
1064	        "Internal Error: getTokensEmbeddings input should be <= prefillChunkSize.",
1065	      );
1066	    }
1067	    const inputData = this.tvm.empty(
1068	      [inputTokens.length],
1069	      "int32",
1070	      this.device,
1071	    );
1072	    inputData.copyFrom(inputTokens);
1073	    const embed: tvmjs.Tensor = this.tvm.detachFromCurrentScope(
1074	      this.embed!(inputData, this.params),
1075	    );
