1081	  /**
1082	   * Compute the number of embedding tokens an image will produce.
1083	   * Must match the model's image_embed output size.
1084	   * Based on mlc_llm/serve/data.py _compute_embed_size.
1085	   */
1086	  private computeImageEmbedSize(
1087	    imageHeight: number,
1088	    imageWidth: number,
1089	  ): number {
1090	    const modelType = this.config.model_type;
1091	    if (modelType === "phi3_v") {
1092	      const [cropH, cropW] = this.calculateCropShape(imageHeight, imageWidth);
1093	      const subTokens = cropH * 12 * (cropW * 12 + 1);
1094	      const glbTokens = 12 * (12 + 1);
1095	      return subTokens + 1 + glbTokens;
1096	    }
1097	    // For models with fixed embed size (e.g. Gemma3V)
1098	    const mmTokens = this.config.model_config?.mm_tokens_per_image;
1099	    if (mmTokens !== undefined) {
1100	      return mmTokens;
1101	    }
1102	    throw new Error(
1103	      `Cannot determine image embed size for model type "${modelType}". ` +
1104	        "Please add mm_tokens_per_image to model_config in mlc-chat-config.json.",
1105	    );
1106	  }
