1108	  /**
1109	   * Calculate resize dimensions per model type.
1110	   * Based on vlm_utils.cc CalculateResizeShape
1111	   */
1112	  private calculateResizeShape(
1113	    imageHeight: number,
1114	    imageWidth: number,
1115	  ): [number, number] {
1116	    switch (this.config.model_type) {
1117	      case "phi3_v": {
1118	        const hdNum = 16;
1119	        const ratio = imageWidth / imageHeight;
1120	        let scale = 1;
1121	        while (scale * Math.ceil(scale / ratio) <= hdNum) {
1122	          scale += 1;
1123	        }
1124	        scale -= 1;
1125	        const newW = scale * 336;
1126	        const newH = Math.floor(newW / ratio);
1127	        return [newH, newW];
1128	      }
1129	      default:
1130	        throw new Error(
1131	          `Unsupported model type "${this.config.model_type}" for image resize.`,
1132	        );
1133	    }
1134	  }
1135	
1136	  /**
1137	   * Calculate crop dimensions per model type.
1138	   * Based on vlm_utils.cc CalculateCropShape / CalculatePadShape
1139	   */
1140	  private calculateCropShape(
1141	    imageHeight: number,
1142	    imageWidth: number,
1143	  ): [number, number] {
1144	    switch (this.config.model_type) {
1145	      case "phi3_v": {
1146	        const [resizedHeight, resizedWidth] = this.calculateResizeShape(
1147	          imageHeight,
1148	          imageWidth,
1149	        );
1150	        const padH = Math.ceil(resizedHeight / 336) * 336;
1151	        return [Math.floor(padH / 336), Math.floor(resizedWidth / 336)];
1152	      }
1153	      default:
1154	        throw new Error(
1155	          `Unsupported model type "${this.config.model_type}" for image crop.`,
1156	        );
1157	    }
1158	  }
