1160	  /**
1161	   * Embed an image input.
1162	   */
1163	  private async getImageEmbeddings(
1164	    inputImage: ImageURL,
1165	  ): Promise<tvmjs.Tensor> {
1166	    this.tvm.beginScope();
1167	    // 1. Transform ImageURL into image input in TVMArray
1168	    const url = inputImage.url;
1169	    const imgData: ImageData =
1170	      this.imageDataCache.get(url) ?? (await getImageDataFromURL(url));
1171	    const pixelValues: Uint8ClampedArray = getRGBArrayFromImageData(imgData);
1172	    const pixelArray = this.tvm
1173	      .empty([imgData.height, imgData.width, 3], "uint32", this.device)
1174	      .copyFrom(pixelValues)
1175	      .view([1, imgData.height, imgData.width, 3]); // NHWC
1176	
1177	    // 2. Calculate resize and crop dimensions
1178	    const [resizeH, resizeW] = this.calculateResizeShape(
1179	      imgData.height,
1180	      imgData.width,
1181	    );
1182	    const [cropH, cropW] = this.calculateCropShape(
1183	      imgData.height,
1184	      imgData.width,
1185	    );
1186	    const resizeHeightShape = this.tvm.makeShapeTuple([resizeH]);
1187	    const resizeWidthShape = this.tvm.makeShapeTuple([resizeW]);
1188	    const cropHeightShape = this.tvm.makeShapeTuple([cropH]);
1189	    const cropWidthShape = this.tvm.makeShapeTuple([cropW]);
1190	
1191	    // 3. embed kernel
1192	    const embed: tvmjs.Tensor = this.tvm.detachFromCurrentScope(
1193	      this.image_embed!(
1194	        pixelArray,
1195	        resizeHeightShape,
1196	        resizeWidthShape,
1197	        cropHeightShape,
1198	        cropWidthShape,
1199	        this.params,
1200	      ),
1201	    );
1202	    const expectedSize = this.computeImageEmbedSize(
1203	      imgData.height,
1204	      imgData.width,
1205	    );
1206	    if (embed.shape[0] !== expectedSize) {
1207	      throw new Error(
1208	        `InternalError: expect embed.shape[0] to be ${expectedSize}, ` +
1209	          `but got ${embed.shape[0]}`,
1210	      );
1211	    }
1212	    this.tvm.endScope();
1213	    this.tvm.attachToCurrentScope(embed); // tracked by scope of embedAndForward
1214	    return embed;
1215	  }
