1217	  /**
1218	   * Embed and forward input data, that can be either array of tokens, or an image.
1219	   * This will increment `this.filledKVCacheLength`.
1220	   *
1221	   * @param inputData data to embed and forward
1222	   * @param inputDataLen length of this inputData, should smaller than prefill chunk size.
1223	   * @returns The logits returned by this forward as tvmjs.Tensor on GPU.
1224	   *
1225	   * @note Precondition: inputData's data length is smaller than prefill chunk size
1226	   */
1227	  private async embedAndForward(
1228	    inputData: Array<Array<number> | ImageURL>,
1229	    inputDataLen: number,
1230	  ): Promise<tvmjs.Tensor> {
1231	    if (inputDataLen > this.prefillChunkSize) {
1232	      throw new Error(
1233	        "InternalError: expect inputDataLen <= this.prefillChunkSize.",
1234	      );
1235	    }
1236	    // TODO: we should combine string data to embed once, then rearrange the embeddings; currently
1237	    // ["hi", imageUrl, "hi"] would call embed kernels 3 times, while 2 would suffice.
1238	
1239	    // 1. Embed all inputData
1240	    this.tvm.beginScope();
1241	    const embeddings: tvmjs.Tensor[] = [];
1242	    for (let i = 0; i < inputData.length; i++) {
1243	      const data = inputData[i];
1244	      if (Array.isArray(data)) {
1245	        embeddings.push(this.getTokensEmbeddings(data));
1246	      } else {
1247	        embeddings.push(await this.getImageEmbeddings(data));
1248	      }
1249	    }
1250	
1251	    // 2. Concatenate embeddings
1252	    let allEmbeddings: tvmjs.Tensor;
1253	    if (embeddings.length === 1) {
1254	      allEmbeddings = embeddings[0];
1255	    } else {
1256	      allEmbeddings = this.tvm.concatEmbeddings(embeddings);
1257	    }
1258	    if (inputDataLen !== allEmbeddings.shape[0]) {
1259	      throw new Error("InternalError: expect seqLen == allEmbeddings.shape[0]");
1260	    }
1261	    allEmbeddings = allEmbeddings.view([1].concat(allEmbeddings.shape));
1262	    // TODO: Should we end this scope here and begin another scope? Will this dispose embeddings to
1263	    // save RAM? We will detach allEmbeddings from this scope and attach to the next scope.
1264	
1265	    // 3. Forward the concatenated embeddings
1266	    const inputLenShape = this.tvm.makeShapeTuple([inputDataLen]);
1267	    const seqIdsTuple = this.tvm.makeShapeTuple([0]);
1268	    const forwardStates = this.getActiveKVStates();
1269	    for (const state of forwardStates) {
1270	      this.fKVCacheBeginForward!(state, seqIdsTuple, inputLenShape);
1271	    }
1272	    let retValue;
1273	    if (inputDataLen > 1) {
1274	      retValue = this.invokePrefill(allEmbeddings, inputDataLen);
1275	    } else {
1276	      retValue = this.invokeDecode(allEmbeddings);
1277	    }
1278	
1279	    // Epilogue
1280	    for (let i = forwardStates.length - 1; i >= 0; --i) {
1281	      this.fKVCacheEndForward!(forwardStates[i]);
1282	    }
1283	    this.filledKVCacheLength += inputDataLen;
1284	    const logits = this.tvm.detachFromCurrentScope(retValue.get(0));
1285	    this.tvm.endScope();
1286	    this.tvm.attachToCurrentScope(logits);
1287	    return logits;
1288	  }
