1290	  private static loadVMFunctionRegistry(
1291	    vm: tvmjs.VirtualMachine,
1292	    names: string[],
1293	  ): VMFunctionRegistry {
1294	    const registry: VMFunctionRegistry = {};
1295	    for (const name of names) {
1296	      try {
1297	        const func = vm.getFunction(name) as unknown;
1298	        if (typeof func === "function") {
1299	          registry[name] = func as tvmjs.PackedFunc;
1300	        }
1301	      } catch {
1302	        // no-op for unexported symbols
1303	      }
1304	    }
1305	    return registry;
1306	  }
