1308	  private static getRequiredVMFunctionByName(
1309	    name: string,
1310	    registry: VMFunctionRegistry,
1311	  ): tvmjs.PackedFunc {
1312	    const func = registry[name];
1313	    if (func !== undefined) {
1314	      return func;
1315	    }
1316	
1317	    const availableNames = Object.entries(registry)
1318	      .filter((entry) => entry[1] !== undefined)
1319	      .map((entry) => entry[0])
1320	      .sort();
1321	    const availableStr =
1322	      availableNames.length === 0 ? "(none)" : availableNames.join(", ");
1323	    throw new Error(
1324	      `Cannot find required VM function \`${name}\`. Available candidate functions: ${availableStr}`,
1325	    );
1326	  }
