1328	  private static getVMFunctionAvailability(
1329	    registry: VMFunctionRegistry,
1330	  ): VMFunctionAvailability {
1331	    return {
1332	      prefill: registry.prefill !== undefined,
1333	      batch_prefill: registry.batch_prefill !== undefined,
1334	      decode: registry.decode !== undefined,
1335	      batch_decode: registry.batch_decode !== undefined,
1336	      create_tir_paged_kv_cache:
1337	        registry.create_tir_paged_kv_cache !== undefined,
1338	      create_rnn_state: registry.create_rnn_state !== undefined,
1339	    };
1340	  }
