1342	  private parseKVStateKind(kvStateKindRaw: unknown): KVStateKind {
1343	    if (kvStateKindRaw === undefined || kvStateKindRaw === null) {
1344	      return "kv_cache";
1345	    }
1346	    if (typeof kvStateKindRaw !== "string") {
1347	      throw new Error(
1348	        `Invalid kv_state_kind in model metadata: expected string, got ${typeof kvStateKindRaw}`,
1349	      );
1350	    }
1351	    const kvStateKind = kvStateKindRaw as KVStateKind;
1352	    if (
1353	      kvStateKind === "kv_cache" ||
1354	      kvStateKind === "rnn_state" ||
1355	      kvStateKind === "hybrid" ||
1356	      kvStateKind === "none"
1357	    ) {
1358	      return kvStateKind;
1359	    }
1360	    throw new Error(
1361	      `Unsupported kv_state_kind in model metadata: ${kvStateKindRaw}`,
1362	    );
1363	  }
