1365	  private static resolveModelABI(
1366	    kvStateKind: KVStateKind,
1367	    availability: VMFunctionAvailability,
1368	  ): ResolvedModelABI {
1369	    const hasSingleKernelPair = availability.prefill && availability.decode;
1370	    const hasBatchKernelPair =
1371	      availability.batch_prefill && availability.batch_decode;
1372	    const availableNames = Object.entries(availability)
1373	      .filter((entry) => entry[1])
1374	      .map((entry) => entry[0])
1375	      .sort();
1376	    const availableStr =
1377	      availableNames.length === 0 ? "(none)" : availableNames.join(", ");
1378	
1379	    if (kvStateKind === "none") {
1380	      throw new Error(
1381	        "kv_state_kind=`none` is not supported in LLMChatPipeline chat runtime.",
1382	      );
1383	    }
1384	
1385	    if (kvStateKind === "hybrid") {
1386	      const missingFunctions: string[] = [];
1387	      if (!availability.batch_prefill) {
1388	        missingFunctions.push("batch_prefill");
1389	      }
1390	      if (!availability.batch_decode) {
1391	        missingFunctions.push("batch_decode");
1392	      }
1393	      if (!availability.create_tir_paged_kv_cache) {
1394	        missingFunctions.push("create_tir_paged_kv_cache");
1395	      }
1396	      if (!availability.create_rnn_state) {
1397	        missingFunctions.push("create_rnn_state");
1398	      }
1399	      if (missingFunctions.length !== 0) {
1400	        throw new Error(
1401	          "Invalid hybrid ABI. Missing required functions: " +
1402	            `${missingFunctions.join(", ")}. ` +
1403	            `Available candidate functions: ${availableStr}`,
1404	        );
1405	      }
1406	      return {
1407	        kvStateKind,
1408	        prefillABI: "batch",
1409	        decodeABI: "batch",
1410	        prefillFunctionName: "batch_prefill",
1411	        decodeFunctionName: "batch_decode",
1412	        needsKVCache: true,
1413	        needsRNNState: true,
1414	      };
1415	    }
1416	
1417	    if (kvStateKind === "rnn_state") {
1418	      if (!availability.create_rnn_state) {
1419	        throw new Error(
1420	          "Invalid rnn_state ABI. Missing required function: create_rnn_state.",
1421	        );
1422	      }
1423	      if (hasSingleKernelPair) {
1424	        return {
1425	          kvStateKind,
1426	          prefillABI: "single",
1427	          decodeABI: "single",
1428	          prefillFunctionName: "prefill",
1429	          decodeFunctionName: "decode",
1430	          needsKVCache: false,
1431	          needsRNNState: true,
1432	        };
1433	      }
1434	      if (hasBatchKernelPair) {
1435	        return {
1436	          kvStateKind,
1437	          prefillABI: "batch",
1438	          decodeABI: "batch",
1439	          prefillFunctionName: "batch_prefill",
1440	          decodeFunctionName: "batch_decode",
1441	          needsKVCache: false,
1442	          needsRNNState: true,
1443	        };
1444	      }
1445	      throw new Error(
1446	        "Invalid rnn_state ABI. Require either `prefill`+`decode` or " +
1447	          "`batch_prefill`+`batch_decode`. " +
1448	          `Available candidate functions: ${availableStr}`,
1449	      );
1450	    }
1451	
1452	    // kv_cache
1453	    if (hasSingleKernelPair) {
1454	      return {
1455	        kvStateKind,
1456	        prefillABI: "single",
1457	        decodeABI: "single",
1458	        prefillFunctionName: "prefill",
1459	        decodeFunctionName: "decode",
1460	        needsKVCache: true,
1461	        needsRNNState: false,
1462	      };
1463	    }
1464	    if (hasBatchKernelPair) {
1465	      return {
1466	        kvStateKind,
1467	        prefillABI: "batch",
1468	        decodeABI: "batch",
1469	        prefillFunctionName: "batch_prefill",
1470	        decodeFunctionName: "batch_decode",
1471	        needsKVCache: true,
1472	        needsRNNState: false,
1473	      };
1474	    }
1475	    throw new Error(
1476	      "Invalid kv_cache ABI. Require either `prefill`+`decode` or " +
1477	        "`batch_prefill`+`batch_decode`. " +
1478	        `Available candidate functions: ${availableStr}`,
1479	    );
1480	  }
