1482	  private requireKVCache(): tvmjs.TVMObject {
1483	    if (this.kvCache === undefined) {
1484	      throw new Error("InternalError: kv cache is not initialized.");
1485	    }
1486	    return this.kvCache;
1487	  }
1488	
1489	  private requireRNNState(): tvmjs.TVMObject {
1490	    if (this.rnnState === undefined) {
1491	      throw new Error("InternalError: rnn state is not initialized.");
1492	    }
1493	    return this.rnnState;
1494	  }
