1496	  private getSingleStateForABI(): tvmjs.TVMObject {
1497	    if (
1498	      this.resolvedModelABI.needsKVCache &&
1499	      !this.resolvedModelABI.needsRNNState
1500	    ) {
1501	      return this.requireKVCache();
1502	    }
1503	    if (
1504	      !this.resolvedModelABI.needsKVCache &&
1505	      this.resolvedModelABI.needsRNNState
1506	    ) {
1507	      return this.requireRNNState();
1508	    }
1509	    throw new Error(
1510	      "InternalError: single-state ABI requested for a hybrid/non-single state model.",
1511	    );
1512	  }
