1514	  private getActiveKVStates(): tvmjs.TVMObject[] {
1515	    const states: tvmjs.TVMObject[] = [];
1516	    if (this.kvCache !== undefined) {
1517	      states.push(this.kvCache);
1518	    }
1519	    if (this.rnnState !== undefined) {
1520	      states.push(this.rnnState);
1521	    }
1522	    if (states.length === 0) {
1523	      throw new Error("InternalError: no kv states initialized.");
1524	    }
1525	    return states;
1526	  }
