1528	  private invokePrefill(
1529	    allEmbeddings: tvmjs.Tensor,
1530	    inputDataLen: number,
1531	  ): any {
1532	    if (this.resolvedModelABI.prefillABI === "single") {
1533	      return this.prefill(
1534	        allEmbeddings,
1535	        this.getSingleStateForABI(),
1536	        this.params,
1537	      );
1538	    }
1539	
1540	    if (this.prefillLogitPositions === undefined) {
1541	      throw new Error(
1542	        "InternalError: batch prefill ABI requires prefillLogitPositions tensor.",
1543	      );
1544	    }
1545	    this.prefillLogitPositionHost[0] = inputDataLen - 1;
1546	    this.prefillLogitPositions.copyFrom(this.prefillLogitPositionHost);
1547	
1548	    if (
1549	      this.resolvedModelABI.needsKVCache &&
1550	      this.resolvedModelABI.needsRNNState
1551	    ) {
1552	      return this.prefill(
1553	        allEmbeddings,
1554	        this.prefillLogitPositions,
1555	        this.requireKVCache(),
1556	        this.requireRNNState(),
1557	        this.params,
1558	      );
1559	    }
1560	    return this.prefill(
1561	      allEmbeddings,
1562	      this.prefillLogitPositions,
1563	      this.getSingleStateForABI(),
1564	      this.params,
1565	    );
1566	  }
1567	
1568	  private invokeDecode(allEmbeddings: tvmjs.Tensor): any {
1569	    if (this.resolvedModelABI.decodeABI === "single") {
1570	      return this.decoding(
1571	        allEmbeddings,
1572	        this.getSingleStateForABI(),
1573	        this.params,
1574	      );
1575	    }
1576	    if (
1577	      this.resolvedModelABI.needsKVCache &&
1578	      this.resolvedModelABI.needsRNNState
1579	    ) {
1580	      return this.decoding(
1581	        allEmbeddings,
1582	        this.requireKVCache(),
1583	        this.requireRNNState(),
1584	        this.params,
1585	      );
1586	    }
1587	    return this.decoding(
1588	      allEmbeddings,
1589	      this.getSingleStateForABI(),
1590	      this.params,
1591	    );
1592	  }
