1594	  // NOTE: caller must call device.sync()
1595	  private updateLogitsOnCPU(logits: tvmjs.Tensor): tvmjs.Tensor {
1596	    if (this.logitsOnCPU == undefined) {
1597	      this.logitsOnCPU = this.tvm.detachFromCurrentScope(
1598	        this.tvm.empty(logits.shape, logits.dtype, this.tvm.cpu()),
1599	      );
