1609	  private async sampleTokenFromLogits(
1610	    logitsOnGPU: tvmjs.Tensor,
1611	    genConfig?: GenerationConfig,
1612	  ) {
1613	    // 0. Get value of temperature, top_p, and various penalties, possibly overridden by genConfig
1614	    // Also load other genConfig items like logit_bias. Consume all fields of `genConfig` here.
1615	    function _hasValue(value: any): boolean {
1616	      // if we use `if value` directly, `value` being 0 evaluates to false, violating semantics
1617	      return value !== undefined && value !== null;
1618	    }
1619	    let temperature: number = this.config.temperature;
1620	    let top_p: number = this.config.top_p;
1621	    let repetition_penalty: number = this.config.repetition_penalty;
1622	    let frequency_penalty: number = this.config.frequency_penalty;
1623	    let presence_penalty: number = this.config.presence_penalty;
1624	    let logit_bias: Record<string, number> | undefined = undefined;
1625	    let logprobs: boolean | undefined = undefined;
1626	    let top_logprobs: number | undefined = undefined;
1627	    let response_format: ResponseFormat | undefined = undefined;
1628	
1629	    if (genConfig !== undefined) {
1630	      if (_hasValue(genConfig.temperature)) {
1631	        temperature = genConfig.temperature!;
1632	      }
1633	      if (_hasValue(genConfig.top_p)) {
1634	        top_p = genConfig.top_p!;
1635	      }
1636	      // TODO: setting top_p to 1.0 by default might run into issues since
1637	      // top_p masking in relax uses < instead of <=
1638	      // Set default top_p to 1.0 if not set
1639	      if (!_hasValue(top_p)) {
1640	        top_p = 1.0;
1641	      }
1642	      if (_hasValue(genConfig.repetition_penalty)) {
1643	        repetition_penalty = genConfig.repetition_penalty!;
1644	      }
1645	      if (_hasValue(genConfig.frequency_penalty)) {
1646	        frequency_penalty = genConfig.frequency_penalty!;
1647	      }
1648	      if (_hasValue(genConfig.presence_penalty)) {
1649	        presence_penalty = genConfig.presence_penalty!;
1650	      }
1651	      // If only one of frequency or presence penalty is set, make the other one 0.0
1652	      if (_hasValue(frequency_penalty) && !_hasValue(presence_penalty)) {
1653	        presence_penalty = 0.0;
1654	      }
1655	      if (_hasValue(presence_penalty) && !_hasValue(frequency_penalty)) {
1656	        frequency_penalty = 0.0;
1657	      }
1658	      if (!_hasValue(frequency_penalty)) {
1659	        frequency_penalty = 0.0;
1660	      }
1661	      if (!_hasValue(presence_penalty)) {
1662	        presence_penalty = 0.0;
1663	      }
1664	      if (_hasValue(genConfig.logit_bias)) {
1665	        logit_bias = genConfig.logit_bias!;
1666	      }
1667	      if (_hasValue(genConfig.logprobs)) {
1668	        logprobs = genConfig.logprobs!;
1669	      }
1670	      if (_hasValue(genConfig.top_logprobs)) {
1671	        top_logprobs = genConfig.top_logprobs!;
1672	      }
1673	      if (_hasValue(genConfig.response_format)) {
1674	        response_format = genConfig.response_format!;
1675	      }
1676	    }
1677	    // Check range validity
1678	    if (top_p <= 0 || top_p > 1) {
1679	      throw new RangeError("top_p", 0, 1);
1680	    }
1681	    if (temperature < 0) {
1682	      throw new MinValueError("temperature", 0);
1683	    }
1684	    if (repetition_penalty <= 0) {
1685	      throw new MinValueError("repetition_penalty", 0);
1686	    }
1687	    if (
1688	      frequency_penalty &&
1689	      (frequency_penalty < -2.0 || frequency_penalty > 2.0)
1690	    ) {
1691	      throw new RangeError("frequency_penalty", -2.0, 2.0);
1692	    }
1693	    if (
1694	      presence_penalty &&
1695	      (presence_penalty < -2.0 || presence_penalty > 2.0)
1696	    ) {
1697	      throw new RangeError("presence_penalty", -2.0, 2.0);
1698	    }
1699	
1700	    const outputTokenBegin = performance.now();
1701	    const grammarConstrained =
1702	      response_format?.type === "json_object" ||
1703	      response_format?.type === "grammar" ||
1704	      response_format?.type === "structural_tag";
1705	
1706	    // 0. Update logitsOnGPU with on-GPU grammar bitmasking
1707	    if (grammarConstrained) {
1708	      const grammarBitmaskBegin = performance.now();
1709	
1710	      this.tvm.beginScope();
1711	      if (this.grammarMatcher === undefined) {
1712	        throw Error("Expect grammar matcher to be initialized.");
1713	      }
1714	
1715	      const tBitmaskStart = performance.now();
1716	      const bitMaskOnCPU: Int32Array =
1717	        await this.grammarMatcher.getNextTokenBitmask();
1718	      this.curRoundGrammarPerTokenTotalTime +=
1719	        (performance.now() - tBitmaskStart) / 1e3;
1720	
1721	      if (bitMaskOnCPU.length !== this.bitmaskSize) {
1722	        throw new Error(
1723	          `InternalError: Expect grammar bitmask to be ` +
1724	            `size ${this.bitmaskSize}, but got ${bitMaskOnCPU.length}.`,
1725	        );
1726	      }
1727	      const bitMaskOnGPU = this.tvm
1728	        .empty([1, this.bitmaskSize], "int32", this.device)
1729	        .copyFrom(bitMaskOnCPU);
1730	      const seqIdsArray = this.tvm
1731	        .empty([1], "int32", this.device)
1732	        .copyFrom([0]);
1733	      this.fapplyBitmask(
1734	        logitsOnGPU.view([1, this.fullVocabSize]),
1735	        seqIdsArray,
1736	        bitMaskOnGPU,
1737	      );
1738	      this.tvm.endScope();
1739	
1740	      if (genConfig?.enable_latency_breakdown) {
1741	        const grammarBitmaskEnd = performance.now();
1742	        const grammarBitmaskTimeSpent =
1743	          (grammarBitmaskEnd - grammarBitmaskBegin) / 1e3;
1744	        this.curRoundLatencyBreakdown.grammarBitmaskTime.push(
1745	          grammarBitmaskTimeSpent,
1746	        );
1747	      }
1748	    }
1749	
1750	    // 1. Apply logitProcessor on CPU
1751	    if (this.logitProcessor !== undefined) {
1752	      // Move logits to CPU
1753	      this.tvm.beginScope();
1754	      this.updateLogitsOnCPU(logitsOnGPU);
1755	      this.tvm.endScope();
1756	      await this.device.sync();
1757	
1758	      const logitProcessorBegin = performance.now();
1759	
1760	      if (this.logitsOnCPU == undefined) {
1761	        throw Error("logits should be assigned");
1762	      }
1763	      let logitsOnCPUArray: Float32Array = <Float32Array>(
1764	        this.logitsOnCPU.toArray()
1765	      );
1766	      logitsOnCPUArray = this.logitProcessor.processLogits(logitsOnCPUArray);
1767	      logitsOnGPU.copyFrom(logitsOnCPUArray);
1768	      this.logitsOnCPU.copyFrom(logitsOnCPUArray);
1769	
1770	      if (genConfig?.enable_latency_breakdown) {
1771	        const logitProcessorEnd = performance.now();
1772	        const logitProcessorTimeSpent =
1773	          (logitProcessorEnd - logitProcessorBegin) / 1e3;
1774	        this.curRoundLatencyBreakdown.logitProcessorTime.push(
1775	          logitProcessorTimeSpent,
1776	        );
1777	      }
1778	    }
1779	
1780	    // 2. Apply logit_bias on GPU
1781	    if (_hasValue(logit_bias)) {
1782	      const logitBiasBegin = performance.now();
1783	
1784	      const numTokens = Object.keys(logit_bias ?? {}).length;
1785	      const pos2seqIds = new Int32Array(numTokens).fill(0);
1786	      const tokenIds = new Int32Array(numTokens);
1787	      const tokenLogitBias = new Float32Array(numTokens);
1788	
1789	      const logitBiasKeys = Object.keys(logit_bias ?? {});
1790	      for (let index = 0; index < numTokens; index++) {
1791	        const tokenId = parseInt(logitBiasKeys[index]);
1792	        tokenIds[index] = tokenId;
1793	        tokenLogitBias[index] = logit_bias![tokenId];
1794	      }
1795	
1796	      this.tvm.beginScope();
1797	
1798	      const pos2seqIdsDevice = this.tvm
1799	        .empty([numTokens], "int32", this.device)
1800	        .copyFrom(pos2seqIds);
1801	
1802	      const tokenIdsDevice = this.tvm
1803	        .empty([numTokens], "int32", this.device)
1804	        .copyFrom(tokenIds);
1805	
1806	      const tokenLogitBiasDevice = this.tvm
1807	        .empty([numTokens], "float32", this.device)
1808	        .copyFrom(tokenLogitBias);
1809	
1810	      this.fapplyLogitBias(
1811	        logitsOnGPU.view([1, this.fullVocabSize]),
1812	        pos2seqIdsDevice,
1813	        tokenIdsDevice,
1814	        tokenLogitBiasDevice,
1815	      );
1816	
1817	      this.tvm.endScope();
1818	
1819	      if (genConfig?.enable_latency_breakdown) {
1820	        const logitBiasEnd = performance.now();
1821	        const logitBiasTimeSpent = (logitBiasEnd - logitBiasBegin) / 1e3;
1822	        this.curRoundLatencyBreakdown.logitBiasTime.push(logitBiasTimeSpent);
1823	      }
1824	    }
1825	
1826	    // 3. Apply penalties to logits on GPU
1827	    if (
1828	      frequency_penalty != 0.0 ||
1829	      presence_penalty != 0.0 ||
1830	      repetition_penalty != 1.0
1831	    ) {
1832	      const appearedTokens = [...this.appearedTokensFreq.keys()];
1833	      const appearedTokensFreqs = [...this.appearedTokensFreq.values()];
1834	
1835	      const numTokens = appearedTokens.length;
1836	
1837	      if (numTokens > 0) {
1838	        const penaltyBegin = performance.now();
1839	
1840	        const pos2seqIds = new Int32Array(numTokens).fill(0);
1841	        const tokenIds = new Int32Array(numTokens).fill(0);
1842	        const tokenCnt = new Int32Array(numTokens).fill(0);
1843	        const penalties = new Float32Array([
1844	          presence_penalty,
1845	          frequency_penalty,
1846	          repetition_penalty,
1847	        ]);
1848	
1849	        tokenIds.set(appearedTokens);
1850	        tokenCnt.set(appearedTokensFreqs);
1851	
1852	        this.tvm.beginScope();
1853	        const seqIdsArray = this.tvm
1854	          .empty([1], "int32", this.device)
1855	          .copyFrom([0]);
1856	
1857	        const pos2seqIdsDevice = this.tvm
1858	          .empty([numTokens], "int32", this.device)
1859	          .copyFrom(pos2seqIds);
1860	
1861	        const tokenIdsDevice = this.tvm
1862	          .empty([numTokens], "int32", this.device)
1863	          .copyFrom(tokenIds);
1864	
1865	        const tokenCntDevice = this.tvm
1866	          .empty([numTokens], "int32", this.device)
1867	          .copyFrom(tokenCnt);
1868	
1869	        const penaltiesDevice = this.tvm
1870	          .empty([1, 3], "float32", this.device)
1871	          .copyFrom(penalties);
1872	
1873	        this.fapplyPenalty(
1874	          logitsOnGPU.view([1, this.fullVocabSize]),
1875	          seqIdsArray,
1876	          pos2seqIdsDevice,
1877	          tokenIdsDevice,
1878	          tokenCntDevice,
1879	          penaltiesDevice,
1880	        );
1881	
1882	        this.tvm.endScope();
1883	
1884	        if (genConfig?.enable_latency_breakdown) {
1885	          const penaltyEnd = performance.now();
1886	          const penaltyTimeSpent = (penaltyEnd - penaltyBegin) / 1e3;
1887	          this.curRoundLatencyBreakdown.penaltyTime.push(penaltyTimeSpent);
1888	        }
1889	      }
1890	    }
1891	
1892	    // TODO: Explore usage of multinomial sampling kernel (currently blocked due to usage
1893	    // of i8) for cases where top_p is not set
1894	    // 4. Sample token from logits
1895	    const sampleBegin = performance.now();
1896	
1897	    // Inplace transform logitsOnCPU to a distribution
1898	    temperature = Math.max(1e-6, temperature); // to prevent division by zero
1899	
1900	    const numSeqs = 1;
1901	    const numProbs = 1;
1902	
1903	    const temperatures = new Float32Array([temperature]);
1904	
1905	    this.tvm.beginScope();
1906	    const temperaturesDevice = this.tvm
1907	      .empty([numSeqs], "float32", this.device)
1908	      .copyFrom(temperatures);
1909	
1910	    let probs = this.fsoftmaxWithTemperature(
1911	      logitsOnGPU.view([numSeqs, numProbs, this.fullVocabSize]),
1912	      temperaturesDevice,
1913	    );
1914	    probs = probs.view([numProbs, this.fullVocabSize]);
1915	
1916	    const topPValue = Math.max(top_p, 1e-5);
1917	    let sampledToken = -1;
1918	    const argsortResults = this.fargsortProbs(probs);
1919	    const sortedProbsDevice = argsortResults.get(0);
1920	    const sortedIndicesDevice = argsortResults.get(1);
1921	    const uniformSamplesDevice = this.tvm.uniform([1], 0.0, 1.0, this.device);
1922	
1923	    const topPHost = new Float32Array(numProbs).fill(-1);
1924	    this.sampleIndices.forEach((row) => {
1925	      topPHost[row] = topPValue;
1926	    });
1927	    this.topPDevice.copyFrom(topPHost);
1928	
1929	    const sampledTokensDevice = this.fsampleWithTopP(
1930	      sortedProbsDevice,
1931	      sortedIndicesDevice,
1932	      uniformSamplesDevice,
1933	      this.sampleIndicesDevice,
1934	      this.topPDevice,
1935	    );
1936	    const sampledTokensHost = this.tvm.detachFromCurrentScope(
1937	      this.tvm
1938	        .empty([numSeqs], "int32", this.tvm.cpu())
1939	        .copyFrom(sampledTokensDevice),
1940	    );
1941	    if (logprobs && top_logprobs! > 0) {
1942	      this.updateLogitsOnCPU(probs);
1943	    }
1944	    this.tvm.endScope();
1945	    await this.device.sync();
1946	
1947	    sampledToken = sampledTokensHost.toArray()[0];
1948	    sampledTokensHost.dispose();
1949	    if (sampledToken < 0) {
1950	      throw new Error("InternalError: failed to sample a valid token.");
1951	    }
1952	
1953	    if (logprobs && top_logprobs! > 0) {
1954	      this.tokenLogprobArray.push(
1955	        this.getTokenLogprob(sampledToken, top_logprobs!),
1956	      );
1957	    }
1958	
1959	    if (genConfig?.enable_latency_breakdown) {
1960	      const sampleEnd = performance.now();
1961	      const sampleTimeSpent = (sampleEnd - sampleBegin) / 1e3;
1962	      this.curRoundLatencyBreakdown.sampleTime.push(sampleTimeSpent);
1963	    }
1964	
1965	    // 5. Update logit processor
1966	    this.logitProcessor?.processSampledToken(sampledToken);
1967	
1968	    // 6. Update grammar matcher with new token
1969	    if (grammarConstrained) {
1970	      if (this.grammarMatcher === undefined) {
1971	        throw Error("Expect grammar matcher to be initialized.");
1972	      }
1973	      const tAcceptStart = performance.now();
1974	      const accepted = this.grammarMatcher.acceptToken(sampledToken);
1975	      this.curRoundGrammarPerTokenTotalTime +=
1976	        (performance.now() - tAcceptStart) / 1e3;
1977	      if (!accepted) {
1978	        throw Error("Grammar matcher rejected the newly sampled token.");
1979	      }
1980	    }
1981	
1982	    if (genConfig?.enable_latency_breakdown) {
1983	      const outputTokenEnd = performance.now();
1984	      const outputTokenTimeSpent = (outputTokenEnd - outputTokenBegin) / 1e3;
1985	      this.curRoundLatencyBreakdown.totalTime.push(outputTokenTimeSpent);
1986	    }
1987	
1988	    return sampledToken;
1989	  }
