1991	  /**
1992	   * Return the an array of a mixture of token arrays and imageURLs (which cannot be represented
1993	   * as tokens). Also return the number of tokens this represents.
1994	   *
1995	   * We first convert the Conversation into a prompt array to be prefilled. Then we encode the
1996	   * text parts, leaving the imageURLs as it is.
1997	   * Example prompts:
1998	   * [
1999	   *   "<|system|>\nSome system prompt\n",
2000	   *   [
2001	   *     "<|user|>\n",
2002	   *     imageURL1,
2003	   *     "\n",
2004	   *     imageURL2,
2005	   *     "\n",
2006	   *     "Some user input<|end|>\n"
2007	   *   ],
2008	   * ]
2009	   *
2010	   * Expected output:
2011	   * [
2012	   *   token array for "<|system|>\nSome system prompt\n<|user|>\n",
2013	   *   imageUrl1,
2014	   *   token array for "\n",
2015	   *   imageUrl2,
2016	   *   token array for "\nSome user input<|end|>\n"
2017	   */
2018	  private async getInputData(): Promise<
2019	    [Array<Array<number> | ImageURL>, number, (image: ImageURL) => number]
2020	  > {
2021	    const ret: Array<Array<number> | ImageURL> = [];
2022	    let curTokens: Array<number> = [];
2023	    let prompts: Array<string | Array<string | ImageURL>>;
2024	
2025	    // 1. Get prompts
2026	    if (this.conversation.isTextCompletion) {
2027	      // 1.1. Non-conversation style
2028	      if (this.filledKVCacheLength !== 0) {
2029	        throw new TextCompletionExpectsKVEmptyError();
2030	      }
2031	      prompts = this.conversation.getPromptArrayTextCompletion();
2032	    } else {
2033	      // 1.2. Conversation style
2034	      if (this.filledKVCacheLength === 0) {
2035	        if (
2036	          this.conversation.config.system_prefix_token_ids !== undefined &&
2037	          this.conversation.config.system_prefix_token_ids !== null
2038	        ) {
2039	          curTokens = [...this.conversation.config.system_prefix_token_ids];
2040	        }
2041	        prompts = this.conversation.getPromptArray(this.config);
2042	      } else {
2043	        prompts = this.conversation.getPromptArrayLastRound(this.config);
2044	      }
2045	    }
2046	
2047	    // 1.5. Preload image dimensions to compute per-image embed sizes
2048	    const imageDimensions = new Map<string, [number, number]>();
2049	    const uniqueImageUrls = new Set<string>();
2050	    for (const prompt of prompts) {
2051	      if (typeof prompt !== "string") {
2052	        for (const content of prompt) {
2053	          if (typeof content !== "string") {
2054	            uniqueImageUrls.add(content.url);
2055	          }
2056	        }
2057	      }
2058	    }
2059	    if (uniqueImageUrls.size > 0 && this.image_embed === undefined) {
2060	      throw new CannotFindImageEmbedError();
2061	    }
2062	    this.imageDataCache.clear();
2063	    await Promise.all(
2064	      Array.from(uniqueImageUrls).map(async (url) => {
2065	        const imgData = await getImageDataFromURL(url);
2066	        this.imageDataCache.set(url, imgData);
2067	        imageDimensions.set(url, [imgData.height, imgData.width]);
2068	      }),
2069	    );
2070	    const getEmbedSize = (image: ImageURL): number => {
2071	      const dims = imageDimensions.get(image.url);
2072	      if (!dims) {
2073	        throw new Error("InternalError: image dimensions not preloaded");
2074	      }
2075	      return this.computeImageEmbedSize(dims[0], dims[1]);
2076	    };
2077	
2078	    // 2. Resolve BOI/EOI tokens
2079	    const cfg = this.config.model_config;
2080	    const boiToken = cfg?.vision_start_token_id ?? cfg?.boi_token_index;
2081	    const eoiToken = cfg?.vision_end_token_id ?? cfg?.eoi_token_index;
2082	
2083	    // 3. Encode all prompts. Iterate through each message in the prompt array, where each
2084	    // prompt can either be a string, or an array of a mixture of string and ImageURLs.
2085	    let numPromptTokens = 0;
2086	    for (let i = 0; i < prompts.length; i++) {
2087	      const curPrompt = prompts[i];
2088	      if (typeof curPrompt === "string") {
2089	        const encoded = this.tokenizer.encode(curPrompt);
2090	        numPromptTokens += encoded.length;
2091	        curTokens.push(...encoded);
2092	      } else {
2093	        for (let j = 0; j < curPrompt.length; j++) {
2094	          const curPromptContent: string | ImageURL = curPrompt[j];
2095	          if (typeof curPromptContent === "string") {
2096	            const encoded = this.tokenizer.encode(curPromptContent);
2097	            numPromptTokens += encoded.length;
2098	            curTokens.push(...encoded);
2099	          } else {
2100	            // Insert BOI token before image if configured
2101	            if (boiToken !== undefined) {
2102	              curTokens.push(boiToken);
2103	              numPromptTokens += 1;
2104	            }
2105	            // push curTokens to ret, push imageUrl, create a new curTokens
2106	            ret.push([...curTokens]);
2107	            ret.push(curPromptContent);
2108	            numPromptTokens += getEmbedSize(curPromptContent);
2109	            curTokens = [];
2110	            // Insert EOI token after image if configured
2111	            if (eoiToken !== undefined) {
2112	              curTokens.push(eoiToken);
2113	              numPromptTokens += 1;
2114	            }
2115	          }
2116	        }
2117	      }
2118	    }
2119	    // Deal with last curTokens
2120	    if (curTokens.length !== 0) {
2121	      ret.push([...curTokens]);
2122	    }
2123	
2124	    // Check if input tokens exceed context window size
2125	    if (
2126	      this.slidingWindowSize == -1 && // There is no limit on contextWindowSize for sliding window
2127	      numPromptTokens + this.filledKVCacheLength > this.contextWindowSize
2128	    ) {
2129	      throw new ContextWindowSizeExceededError(
2130	        numPromptTokens,
2131	        this.contextWindowSize,
2132	      );
2133	    }
2134	    return [ret, numPromptTokens, getEmbedSize];
2135	  }
