2137	  async forwardTokensAndSample(
2138	    inputIds: Array<number>,
2139	    isPrefill: boolean,
2140	  ): Promise<number> {
2141	    const tstart = performance.now();
2142	    this.tvm.beginScope();
2143	    // 1. Chunk inputData if needed
2144	    const inputData: Array<Array<number>> = [inputIds];
2145	    const retGetChunks = getChunkedPrefillInputData(
2146	      inputData,
2147	      this.prefillChunkSize,
2148	      () => 0, // text-only path, no images
2149	    );
2150	    const chunks: Array<Array<number> | ImageURL>[] = retGetChunks[0];
2151	    const chunkLens: Array<number> = retGetChunks[1];
2152	
2153	    // 2. Prefill each chunk
2154	    let logitsOnGPU: tvmjs.Tensor;
2155	    for (let i = 0; i < chunks.length; i++) {
2156	      const chunk = chunks[i];
2157	      const chunkLen = chunkLens[i];
2158	      const prevFilledLen = this.filledKVCacheLength;
2159	      logitsOnGPU = await this.embedAndForward(chunk, chunkLen);
2160	      if (this.filledKVCacheLength !== prevFilledLen + chunkLen) {
2161	        throw new Error(
2162	          "Internal Error: filledKVCacheLength does not match expected value.",
2163	        );
2164	      }
2165	    }
2166	
2167	    // 3. Sample next token
2168	    const nextToken = await this.sampleTokenFromLogits(logitsOnGPU!);
2169	    this.tvm.endScope();
2170	
2171	    // 4. Stats
2172	    const tend = performance.now();
2173	    if (isPrefill) {
2174	      // We assume that if the input has more than 1 token
2175	      this.prefillTotalTime += (tend - tstart) / 1e3;
2176	      this.prefillTotalTokens += inputIds.length;
2177	      this.curRoundPrefillTotalTokens += inputIds.length;
2178	      this.curRoundPrefillTotalTime += (tend - tstart) / 1e3;
2179	    } else {
2180	      this.decodingTotalTime += (tend - tstart) / 1e3;
2181	      this.decodingTotalTokens += 1;
2182	      this.curRoundDecodingTotalTokens += 1;
2183	      this.curRoundDecodingTotalTime += (tend - tstart) / 1e3;
2184	    }
2185	    return nextToken;
2186	  }
