2188	  /**
2189	   * Based on `sampledToken` and `this.logitsOnCPU`, which becomes a distribution after
2190	   * calling `this.tvm.applySoftmaxWithTemperature()`, generate `ChatCompletionTokenLogprob` and
2191	   * update `this.tokenLogprobArray`.
2192	   *
2193	   * @param sampledToken The token ID sampled.
2194	   * @param top_logprobs Number of top tokens to include; `top_logprobs` in `ChatCompletionRequest`.
2195	   *
2196	   * @return The `ChatCompletionTokenLogprob` for this single autoregressive step.
2197	   */
2198	  private getTokenLogprob(
2199	    sampledToken: number,
2200	    top_logprobs: number,
2201	  ): ChatCompletionTokenLogprob {
2202	    if (this.logitsOnCPU == undefined) {
2203	      throw Error("logits should be assigned");
2204	    }
2205	    // Array of [token, prob] pairs, sorted with highest prob first.
2206	    const logitsOnCPUArray = <Float32Array>this.logitsOnCPU.toArray();
2207	    const topLogprobs = getTopProbs(top_logprobs!, logitsOnCPUArray);
2208	
2209	    // Get entry for sampled token first
2210	    const textEncoder = new TextEncoder();
2211	    const tokenStr = this.tokenizer.decode(new Int32Array([sampledToken]));
2212	    const bytes: Array<number> = Array.from(textEncoder.encode(tokenStr));
2213	    const logprob = Math.log(logitsOnCPUArray[sampledToken]);
2214	
2215	    // Populate `top_logprobs`
2216	    const topLogprobArray: Array<TopLogprob> = [];
2217	    for (let i = 0; i < top_logprobs; i++) {
2218	      const tokenID_i = topLogprobs[i][0];
2219	      const prob_i = topLogprobs[i][1];
2220	      const tokenStr_i = this.tokenizer.decode(new Int32Array([tokenID_i]));
2221	      topLogprobArray.push({
2222	        token: tokenStr_i,
2223	        bytes: Array.from(textEncoder.encode(tokenStr_i)) as Array<number>,
2224	        logprob: Math.log(prob_i),
2225	      } as TopLogprob);
2226	    }
2227	
2228	    return {
2229	      token: tokenStr,
2230	      bytes: bytes,
2231	      logprob: logprob,
2232	      top_logprobs: topLogprobArray,
2233	    } as ChatCompletionTokenLogprob;
2234	  }
2235	
2236	  /**
2237	   * Synchronize the device.
2238	   */
2239	  async sync(): Promise<void> {
2240	    // Is it equivalent to this.tvm.sync()?
2241	    await this.device.sync();
2242	  }
2243	
2244	  async evaluate() {
2245	    // run a canonical evaluation of the flow
2246	    this.resetKVCache();
2247	    this.filledKVCacheLength = 0;
2248	
2249	    const testPrompt = "The capital of Canada is";
2250	    const ids = await this.tokenizer.encode(testPrompt);
2251	    const tokens = Array.from(ids);
2252	    tokens.unshift(this.bosTokenId);
2253	    if (tokens.length == 0) {
2254	      throw Error("empty token");
2255	    }
2256	
2257	    this.tvm.beginScope();
2258	    const prefillChunk: Array<Array<number>> = [tokens] as Array<Array<number>>;
2259	    const prefillChunkLen = tokens.length;
2260	    const prefillStart = performance.now();
2261	    await this.embedAndForward(prefillChunk, prefillChunkLen);
2262	    this.tvm.endScope();
2263	    await this.device.sync();
2264	
2265	    const decodingStart = performance.now();
2266	
2267	    this.tvm.beginScope();
2268	    const decodeChunk: Array<Array<number>> = [[6234]];
2269	    const decodeChunkLen = 1;
2270	    const logitsOnCPU = this.updateLogitsOnCPU(
2271	      await this.embedAndForward(decodeChunk, decodeChunkLen),
2272	    );
2273	    await this.device.sync();
2274	    this.tvm.endScope();
2275	
2276	    const decodingEnd = performance.now();
2277	    const msg =
2278	      `prefill-time=${((decodingStart - prefillStart) / 1000).toFixed(4)} sec` +
2279	      `decoding-time=${((decodingEnd - decodingStart) / 1000).toFixed(4)} sec`;
2280	
2281	    // simply log tokens for eyeballing.
