507	  ): AsyncGenerator<ChatCompletionChunk | Completion, void, void> {
508	    // Since it is an async generator, we need to do fine-grained try-catch to ensure lock is
509	    // released only when errors occur. Then release at the very end when no error occurs.
510	    // TODO: This makes code less readable, is there a better way to do this?
511	    const lock = this.loadedModelIdToLock.get(model)!;
512	
513	    // 0. Pre-processing
514	    const isChatCompletion = "messages" in request;
515	    const isFunctionCalling =
516	      "tools" in request &&
517	      request.tools !== undefined &&
518	      request.tools !== null;
519	    try {
520	      if (isFunctionCalling && !isChatCompletion) {
521	        throw new Error(
522	          "Expect `chat.completions` with tools, not `completions`.",
523	        );
524	      }
525	      postInitAndCheckGenerationConfigValues(genConfig);
526	      if (request.seed !== null && request.seed !== undefined) {
527	        pipeline.setSeed(request.seed);
528	      }
529	    } catch (err) {
530	      await lock.release();
531	      throw err;
532	    }
533	
534	    // 1. Helper function that generates the chunk
535	    const created = getUnixTimestampSeconds();
536	    const id = crypto.randomUUID();
537	    this.interruptSignal = false;
538	    let prevMessageLength = 0; // to know where to start slicing the delta; does not count �
539	
540	    function _countTrailingReplacementChar(curMessage: string): number {
541	      let cntr = 0;
542	      for (let i = curMessage.length - 1; i >= 0; i--) {
543	        if (curMessage.charAt(i) === "�") {
544	          cntr += 1;
545	        } else {
546	          return cntr;
547	        }
548	      }
549	      return cntr;
550	    }
551	
552	    async function _getChunk(
553	      selectedPipeline: LLMChatPipeline,
554	    ): Promise<ChatCompletionChunk | Completion | undefined> {
555	      // Remove the replacement character (U+FFFD) from the response to handle emojis.
556	      // Each emoji is made up of multiples of 4 tokens; when truncated, it is displayed as �, so
557	      // we skip this delta until a full emoji is rendered
558	      // TODO(Charlie): This does not consider cases of � not being emoji, need to fix with Streamer
559	      const curMessage = selectedPipeline.getMessage();
560	      const numTrailingReplacementChar =
561	        _countTrailingReplacementChar(curMessage);
562	      if (numTrailingReplacementChar % 4 !== 0) {
563	        return undefined;
564	      }
565	
566	      const deltaMessage = curMessage.slice(prevMessageLength);
567	      prevMessageLength = curMessage.length;
568	      const logprobs = request.logprobs
569	        ? ({
570	            content: selectedPipeline.getTokenLogprobArray().slice(-1), // always the last entry
571	          } as ChatCompletionChunk.Choice.Logprobs)
572	        : null;
573	      if (isChatCompletion) {
574	        const chunk: ChatCompletionChunk = {
575	          id: id,
576	          choices: [
577	            {
578	              delta: { content: deltaMessage, role: "assistant" },
579	              finish_reason: null, // not finished yet
580	              index: 0,
581	              logprobs: logprobs,
582	            },
583	          ],
584	          model: model,
585	          object: "chat.completion.chunk",
586	          created: created,
587	        };
588	        return chunk;
589	      } else {
590	        const chunk: Completion = {
591	          id: id,
592	          choices: [
593	            {
594	              text: deltaMessage,
595	              finish_reason: null, // not finished yet
596	              index: 0,
597	              logprobs: logprobs,
598	            },
599	          ],
600	          model: model,
601	          object: "text_completion",
602	          created: created,
603	        };
604	        return chunk;
605	      }
606	    }
